if hashlib.sha256(payload).hexdigest() != 'c3fe92934678e1d1e3df1cff711d57a88e07f66e4cc76ea06f8f2d42af3e0241':
    raise SystemExit('Embedded archive hash mismatch')
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    for member in archive.infolist():
        relative = pathlib.PurePosixPath(member.filename)
        if relative.is_absolute() or '..' in relative.parts:
            raise SystemExit('Unsafe archive path')
        destination = target.joinpath(*relative.parts)
        if not destination.resolve().is_relative_to(target):
            raise SystemExit('Destination escapes project')
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(archive.read(member))
for line in (target/'MANIFEST.sha256').read_text().splitlines():
    digest, name = line.split('  ', 1)
    if hashlib.sha256((target/name).read_bytes()).hexdigest() != digest:
        raise SystemExit('Extracted file hash mismatch: '+name)
print('Complete project extracted and verified.')
PY_EOD_PAYLOAD
cp -- "$script_path" "$target/setup_and_push.sh"
chmod +x "$target/setup_and_push.sh"
if [[ "$mode" == push ]]; then
  git -C "$target" add -- README.md requirements.txt constraints.txt src tests docs .github .env.example .gitignore MANIFEST.sha256 setup_and_push.sh
  if ! git -C "$target" diff --cached --quiet; then
    git -C "$target" commit -m "Build hybrid EOD Alpaca bot with strict execution guards"
  fi
  git -C "$target" push -u origin main
  echo 'Published. Scheduled runs remain simulations until TRADING_ENABLED=true.'
else
  echo 'Extraction only: no Git publication and no trading.'
fi
